41		public static HashMap<String, Integer> retrieveTags(Note note) {
42			HashMap<String, Integer> tagsMap = new HashMap<>();
43			for (String token : (note.getTitle() + " " + note.getContent()).replaceAll("\n", " ").trim().split(" ")) {
44				if (RegexPatternsConstants.HASH_TAG.matcher(token).matches()) {
45					int count = tagsMap.get(token) == null ? 0 : tagsMap.get(token);
46					tagsMap.put(token, ++count);
47				}
48			}
49			return tagsMap;
50		}
