53	    public static Pair<String, List<Tag>> addTagToNote(List<Tag> tags, Integer[] selectedTags, Note note) {
54	        StringBuilder sbTags = new StringBuilder();
55	        List<Tag> tagsToRemove = new ArrayList<>();
56	        HashMap<String, Integer> tagsMap = retrieveTags(note);
57	
58	        List<Integer> selectedTagsList = Arrays.asList(selectedTags);
59	        for (int i = 0; i < tags.size(); i++) {
60	            if (mapContainsTag(tagsMap, tags.get(i))) {
61	                if (!selectedTagsList.contains(i)) {
62	                    tagsToRemove.add(tags.get(i));
63	                }
64	            } else {
65	                if (selectedTagsList.contains(i)) {
66	                    if (sbTags.length() > 0) {
67	                        sbTags.append(" ");
68	                    }
69	                    sbTags.append(tags.get(i));
70	                }
71	            }
72	        }
73	        return Pair.create(sbTags.toString(), tagsToRemove);
74	    }
