public static Pair<String, String> removeTag(String noteTitle, String noteContent, List<Tag> tagsToRemove) {
    String title = noteTitle, content = noteContent;
    for (Tag tagToRemove : tagsToRemove) {
        title = removeTagFromText(title, tagToRemove.getText());
        content = removeTagFromText(content, tagToRemove.getText());
    }
    return new Pair<>(title, content);
}


/**
 * Removes from the given text only the occurrences of the tag that are standalone words, so
 * that removing "#tag" will not affect similar ones like "#tagged" or "#tag2".
 */
private static String removeTagFromText(String text, String tagText) {
    if (TextUtils.isEmpty(text) || TextUtils.isEmpty(tagText)) {
        return text;
    }
    // The tag is quoted to avoid any interpretation of its characters as regular expression
    // ones and it's matched only when surrounded by whitespaces (or text boundaries)
    Pattern pattern = Pattern.compile("(^|\\s)" + Pattern.quote(tagText) + "(?=\\s|$)");
    return pattern.matcher(text).replaceAll("$1");
}

